(()=>{const t=location.hostname;if(!(/(^|\.)youtube\.com$/.test(t)||t==="youtu.be")&&!window.__ytdlThirdPartyInjectorLoaded){window.__ytdlThirdPartyInjectorLoaded=!0;try{import(chrome.runtime.getURL("detectors/youtube-detector.js")).then(()=>{let e=0;const r=setInterval(()=>{(/(^|\.)youtube\.com$/.test(location.hostname)||location.hostname==="youtu.be")&&(document.querySelectorAll("div[data-ytdl-dl-btn]").forEach(n=>n.remove()),clearInterval(r)),++e>30&&clearInterval(r)},1e3)}).catch(e=>console.warn("YTDL embed injector import failed:",e))}catch(o){console.warn("YTDL embed injector error:",o)}}})();
